mapper.select:
select f.FileTitle as ctFileTitle, t.TaskName as ctTaskName, u.U_Name as ctSendName, flow.FlowName as ctFlowName, pro.P_Name as pName, sec.Sec_Name as secName, con.Con_Name as conName, f.T_Code as tCode,
from SYS_CoordinationTask ct left join SYS_Task t on t.TaskID=ct.CT_TaskID left join SYS_Flow flow on flow.FlowID=ct.CT_FlowID left join Sys_File f on f.FileID=ct.CT_FileID left join Sys_User u on u.U_Id=ct.CT_SendUser left join Pre_Project pro on pro.P_ID=f.FileProject left join Sec_Info sec on sec.Sec_Id=f.FileSectionID left join Con_Contract con on con.Con_Id=f.FileContract
ct.CT_User=#{params.userId}
and ct.CT_Name like concat('%',#{params.ctName},'%')
and likePname(#{params.pName},pro.P_Id)=true
and pro.P_Name like concat('%',#{params.pName},'%')
and con.Con_Name like concat('%',#{params.conName},'%')
and u.U_Name like concat('%',#{params.ctSendUser},'%')
and ct.Te_Id = #{params.teId}
order by ct.${params.sortFiled} ${params.sortType}
limit #{params.start},#{params.size}

select f.T_Code as tCode,
count(*)  as total
from SYS_CoordinationTask tk
left join Sys_File f on f.FileId=tk.CT_FileID
where f.T_Code in

    #{code}


    and tk.Ct_User=#{params.uId}


    and tk.Te_Id = #{params.teId}

group by f.T_Code
